#!/usr/bin/env python3
# L001 (NARROWED FRAGMENT) verifier: exact rational, fail-closed, deterministic.
# Entry point: verify(witness) raises on ANY failed check; returns True on pass.
# Certifies ONLY: R(x) <= 1 for every integer x in [1,200] under the frozen convention.
from fractions import Fraction

def verify(witness):
    if witness.get("embedded") is not True:
        raise RuntimeError("FAIL: witness marker missing")
    if tuple(witness["range"]) != (1, 200):
        raise RuntimeError("FAIL: range mismatch")

    def primes_upto(N):
        if N < 2:
            raise RuntimeError("FAIL: bad prime bound")
        sieve = [True]*(N+1)
        sieve[0] = sieve[1] = False
        i = 2
        while i*i <= N:
            if sieve[i]:
                for j in range(i*i, N+1, i):
                    sieve[j] = False
            i += 1
        return [k for k in range(2, N+1) if sieve[k]]

    P = primes_upto(3000)
    if len(P) < 202:
        raise RuntimeError("FAIL: insufficient primes")
    d = [0]*len(P)
    for n in range(1, len(P)):
        d[n] = P[n] - P[n-1]

    def R(x):
        ns = [n for n in range(1, x) if n < len(d)]
        if not ns:
            raise RuntimeError("FAIL: empty window at x=%d" % x)
        M1 = max(Fraction(d[n]) for n in ns)
        if M1 <= 0:
            raise RuntimeError("FAIL: nonpositive max gap")
        M2 = max(Fraction(d[n]) * Fraction(d[n-1]) for n in ns)
        return M2 / (M1*M1)

    for x in range(1, 201):
        if R(x) > Fraction(1):
            raise RuntimeError("FAIL: R(%d) > 1" % x)
    return True

verify({"embedded": True, "range": [1, 200]})
